package com.bplus.share;
import android.app.*;import android.widget.*;import android.view.Gravity;import org.json.*;
/** Fetch fresh opted-in data from an authenticated active peer; never cache contact values. */
public final class ProfileCard{
 public static void show(Activity a,String id){JSONObject peer=Store.peerById(id);if(peer==null)return;LinearLayout col=Ui.col(a);Ui.pad(col,22,18,22,20,a);col.setGravity(Gravity.CENTER_HORIZONTAL);col.addView(Profile.avatar(a,peer,144));col.addView(Ui.t(a,peer.optString("name"),22,Ui.text,App.cairoB));col.addView(Ui.t(a,"@"+peer.optString("username"),16,Ui.accent,App.cairoSB));TextView fields=Ui.t(a,a.getString(R.string.profile_loading),14,Ui.dim,App.cairo);col.addView(fields,Ui.lp(-1,-2));AlertDialog dialog=new AppDialog(a).setTitle(R.string.profile_details).setView(col).setPositiveButton(android.R.string.ok,null).create();dialog.show();new Thread(()->{String value;try{JSONObject current=Store.peerById(id);if(current==null)throw new java.io.IOException();JSONObject reply=Net.contactProfile(current);if(reply.optString("email").length()>254||reply.optString("phone").length()>40)throw new java.io.IOException();String email=reply.optString("email"),phone=reply.optString("phone");value=a.getString(R.string.profile_email)+"\n"+(email.isEmpty()?a.getString(R.string.profile_hidden):email)+"\n\n"+a.getString(R.string.profile_phone)+"\n"+(phone.isEmpty()?a.getString(R.string.profile_hidden):phone);}catch(Exception e){value=a.getString(R.string.profile_details_unavailable);}final String text=value;a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed()&&dialog.isShowing())fields.setText(Store.peerById(id)==null?a.getString(R.string.not_paired):text);});}).start();}
}
